create table if not exists public.admin_ad_expenses(id uuid primary key default gen_random_uuid(),expense_date date not null,platform text not null check(platform in('facebook_ads','google_ads')),campaign_name text,amount numeric(14,2) not null check(amount>0),notes text,created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists admin_ad_expenses_date_platform_idx on public.admin_ad_expenses(expense_date,platform);
alter table public.admin_ad_expenses enable row level security;
create policy admin_ad_expenses_read_admins on public.admin_ad_expenses for select to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.is_active and p.role='admin'));
create policy admin_ad_expenses_insert_admins on public.admin_ad_expenses for insert to authenticated with check(created_by=(select auth.uid()) and exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.is_active and p.role='admin'));
create policy admin_ad_expenses_update_admins on public.admin_ad_expenses for update to authenticated using(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.is_active and p.role='admin')) with check(exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.is_active and p.role='admin'));
grant select,insert,update on public.admin_ad_expenses to authenticated;
create or replace function public.get_admin_report_intelligence(p_start_date date,p_end_date date) returns jsonb language plpgsql security definer set search_path='' as $function$
declare result jsonb;range_start timestamptz;range_end timestamptz;day_count int;
begin
if not exists(select 1 from public.profiles where id=auth.uid() and is_active and role='admin') then raise exception 'Admin access required';end if;
if p_start_date is null or p_end_date is null or p_end_date<p_start_date then raise exception 'Select a valid date range';end if;
if p_end_date-p_start_date>366 then raise exception 'Date range cannot exceed 366 days';end if;
range_start:=p_start_date::timestamp at time zone 'Asia/Kolkata';range_end:=(p_end_date+1)::timestamp at time zone 'Asia/Kolkata';day_count:=p_end_date-p_start_date+1;
with totals as(select coalesce((select sum(amount) from public.admin_ad_expenses where expense_date between p_start_date and p_end_date),0) spend,coalesce((select sum(amount) from public.admin_ad_expenses where platform='facebook_ads' and expense_date between p_start_date and p_end_date),0) facebook_spend,coalesce((select sum(amount) from public.admin_ad_expenses where platform='google_ads' and expense_date between p_start_date and p_end_date),0) google_spend,(select count(*) from public.admin_players where registered_at>=range_start and registered_at<range_end) registrations,(select count(*) from public.admin_players where ftd_at>=range_start and ftd_at<range_end) ftd)
select jsonb_build_object('range',jsonb_build_object('start_date',p_start_date,'end_date',p_end_date,'days',day_count),'totals',jsonb_build_object('spend',spend,'facebook_spend',facebook_spend,'google_spend',google_spend,'registrations',registrations,'ftd',ftd,'cost_per_registration',case when registrations>0 then round(spend/registrations,2) end,'cost_per_ftd',case when ftd>0 then round(spend/ftd,2) end,'ftd_conversion',case when registrations>0 then round(100.0*ftd/registrations,2) end,'average_daily_spend',round(spend/day_count,2)),'daily',(select coalesce(jsonb_agg(to_jsonb(d) order by d.date_value),'[]'::jsonb) from(select day::date date_value,coalesce((select sum(e.amount) from public.admin_ad_expenses e where e.expense_date=day::date),0) spend,coalesce((select sum(e.amount) from public.admin_ad_expenses e where e.expense_date=day::date and e.platform='facebook_ads'),0) facebook_spend,coalesce((select sum(e.amount) from public.admin_ad_expenses e where e.expense_date=day::date and e.platform='google_ads'),0) google_spend,(select count(*) from public.admin_players p where p.registered_at>=day and p.registered_at<day+interval '1 day') registrations,(select count(*) from public.admin_players p where p.ftd_at>=day and p.ftd_at<day+interval '1 day') ftd from generate_series(range_start,range_end-interval '1 day',interval '1 day') day)d)) into result from totals;return result;end;$function$;
revoke all on function public.get_admin_report_intelligence(date,date) from public,anon;grant execute on function public.get_admin_report_intelligence(date,date) to authenticated;